mapper.update:
/*EdiBmsSendMapper.batchUpdateEdiBmsInSendSucc : GOVCBR632(반입신고서) XML 송신성공 건 LAST_POD_STATUS 업데이트 */

UPDATE TB_BMS_IN
   SET LAST_POD_DATE = GETDATE()
     , LAST_POD_STATUS = 'BMS03' /* 송신 */
	 , UPDATE_USER_ID = #{updateUserId}
	 , UPDATE_DATE_TIME = GETDATE()
 WHERE IN_NO = #{inNo}
 AND LAST_POD_STATUS IN ('', 'BMS01', 'BMS02') /*입력, 송신실패 */

/*EdiBmsSendMapper.batchUpdateEdiBmsInSendErr : GOVCBR632(반입신고서) XML 송신실패 건 LAST_POD_STATUS 업데이트 */

UPDATE TB_BMS_IN
   SET LAST_POD_DATE = GETDATE()
     , LAST_POD_STATUS = 'BMS02' /* 송신실패 */
	 , UPDATE_USER_ID = #{updateUserId}
	 , UPDATE_DATE_TIME = GETDATE()
 WHERE IN_NO = #{inNo}
 AND LAST_POD_STATUS IN ('', 'BMS01', 'BMS02', 'BMS03') /*입력, 송신실패, 전송 */

/*EdiBmsSendMapper.batchUpdateEdiBmsOutSendSucc : GOVCBR6NB(반출신고서) XML 송신성공 건 LAST_POD_STATUS 업데이트 */

UPDATE TB_BMS_OUT
   SET LAST_POD_DATE = GETDATE()
	 , LAST_POD_STATUS = 'BMS03' /* 송신 */
	 , UPDATE_USER_ID = #{updateUserId}
	 , UPDATE_DATE_TIME = GETDATE()
 WHERE OUT_NO = #{outNo}
   AND LAST_POD_STATUS NOT IN ('BMS04', 'BMS05', 'BMSA4')  /* 접수 오류 */

/*EdiBmsSendMapper.batchUpdateEdiBmsOutSendErr : GOVCBR6NB(반출신고서) XML 송신실패 건 LAST_POD_STATUS 업데이트 */

UPDATE TB_BMS_OUT
   SET LAST_POD_DATE = GETDATE()
	 , LAST_POD_STATUS = 'BMS02' /* 송신실패 */
	 , UPDATE_USER_ID = #{updateUserId}
	 , UPDATE_DATE_TIME = GETDATE()
 WHERE OUT_NO = #{outNo}
   AND LAST_POD_STATUS NOT IN ('BMS04', 'BMS05', 'BMSA4') /* 접수 오류 */

/*EdiBmsSendMapper.batchUpdateEdiBmsOutNoticeSendSucc : GOVCBR5II(반출통고목록보고서) XML 송신성공 건 LAST_POD_STATUS 업데이트 */
UPDATE TB_BMS_OUT_NOTICE
   SET LAST_POD_DATE = GETDATE()
	 , LAST_POD_STATUS = 'BMS03' /* 송신 */
	 , UPDATE_USER_ID = #{updateUserId}
	 , UPDATE_DATE_TIME = GETDATE()
 WHERE OUT_NOTICE_NO = #{outNoticeNo}
 AND LAST_POD_STATUS IN ('', 'BMS01', 'BMS02') /*입력, 송신실패 */

/*EdiBmsSendMapper.batchUpdateEdiBmsOutNoticeSendErr : GOVCBR5II(반출통고목록보고서) XML 송신실패 건 LAST_POD_STATUS 업데이트 */
UPDATE TB_BMS_OUT_NOTICE
   SET LAST_POD_DATE = GETDATE()
	 , LAST_POD_STATUS = 'BMS02' /* 송신실패 */
	 , UPDATE_USER_ID = #{updateUserId}
	 , UPDATE_DATE_TIME = GETDATE()
 WHERE OUT_NOTICE_NO = #{outNoticeNo}
 AND LAST_POD_STATUS IN ('', 'BMS01', 'BMS02') /*입력, 송신실패 */

/*EdiBmsSendMapper.batchUpdateEdiBmsChangeSendSucc : GOVCBR5LC(반입신고정정신청서) or GOVCBR5LD(반출신고정정신청서) XML 송신성공 건 LAST_POD_STATUS 업데이트 */
UPDATE TB_BMS_CHANGE
   SET LAST_POD_DATE = GETDATE()
	 , LAST_POD_STATUS = 'BMS03' /* 송신 */
	 , UPDATE_USER_ID = #{updateUserId}
	 , UPDATE_DATE_TIME = GETDATE()
 WHERE CHANGE_NO = #{changeNo}
 AND LAST_POD_STATUS IN ('', 'BMS01', 'BMS02') /*입력, 송신실패 */

/*EdiBmsSendMapper.batchUpdateEdiBmsChangeSendErr : GOVCBR5LC(반입신고정정신청서) or GOVCBR5LD(반출신고정정신청서) XML 송신실패 건 LAST_POD_STATUS 업데이트 */
UPDATE TB_BMS_CHANGE
   SET LAST_POD_DATE = GETDATE()
	 , LAST_POD_STATUS = 'BMS02' /* 송신실패 */
 WHERE CHANGE_NO = #{changeNo}
  AND LAST_POD_STATUS IN ('', 'BMS01', 'BMS02') /*입력, 송신실패 */

/*EdiBmsSendMapper.batchUpdateEdiBmsAbnormalSend : GOVCBRDKO(특송화물 반입물품 이상보고서) XML 전송 후 DB 업데이트 */
UPDATE TB_BMS_ABNORMAL
   SET LAST_POD_DATE = GETDATE()
	 , LAST_POD_STATUS = 'BMS03' /* 송신 */
	 , UPDATE_USER_ID = #{updateUserId}
	 , UPDATE_DATE_TIME = GETDATE()
 WHERE ABN_NO = #{abnNo}
 AND LAST_POD_STATUS IN ('', 'BMS01', 'BMS02') /*입력, 송신실패 */

/*EdiBmsSendMapper.batchUpdateEdiBmsAbnormalCorrSend : GOVCBRDKP(특송화물 반입물품 이상보고 정정신청서) XML 전송 후 DB 업데이트 */
UPDATE TB_BMS_ABNORMAL_CHANGE
   SET LAST_POD_DATE = GETDATE()
	 , LAST_POD_STATUS = 'BMS03' /* 송신 */
	 , UPDATE_USER_ID = #{updateUserId}
	 , UPDATE_DATE_TIME = GETDATE()
 WHERE ABN_CHANGE_NO = #{abnChangeNo}
  AND LAST_POD_STATUS IN ('', 'BMS01', 'BMS02') /*입력, 송신실패 */
